export interface StoryLog {
  id: number;          // storyProgress.ts 잠금 해제 번호와 동일
  title: string;
  text: string;        // 본문 (개행 \n 지원)
  videoKey?: string;   // Phaser 비디오 키 (미설정 시 텍스트만 표시)
  videoPath?: string;  // public/ 기준 경로
  unlockHint: string;  // 잠긴 상태에서 보여줄 힌트
}

/**
 * 전체 스토리 로그 목록.
 * id는 storyProgress.ts의 unlock() 번호와 1:1 대응.
 * 영상이 준비되면 videoKey/videoPath 필드를 채우면 됨.
 */
export const STORY_LOGS: StoryLog[] = [
  {
    id: 1,
    title: '첫 번째 신호',
    text: '처음으로 낯선 목소리가 들렸다.\n\n무너지는 코드 더미 아래에서 다른 존재가 손을 뻗었다.\n\n이 공간이 텅 비어 있지 않다는 걸 그때 처음 알았다.',
    unlockHint: '동료를 처음 만나면 열립니다',
  },
  {
    id: 2,
    title: '둘의 법칙',
    text: '두 번째 신호가 확인됐다.\n\n이제 우린 둘이다. 혼자일 때보다 더 먼 곳을 볼 수 있다.\n\n오류가 쏟아지는 하늘 아래, 우리는 각자의 속도로 달린다.',
    unlockHint: '캐릭터를 2명 보유하면 열립니다',
  },
  {
    id: 3,
    title: '500번의 발걸음',
    text: '500번의 발걸음.\n\n출발점은 이미 시야에서 사라졌다.\n\n앞에는 아직 보이지 않는 무언가가 있다. 그래도 달린다.',
    unlockHint: '달린 거리 500m를 넘기면 열립니다',
  },
  {
    id: 4,
    title: 'SKOR의 의미',
    text: 'SKOR는 이 세계에서의 증거다.\n\n생존한 시간, 피한 오류들, 그리고 남은 의지.\n\n100이 쌓였다. 너는 충분히 존재했다.',
    unlockHint: 'SKOR를 100 이상 획득하면 열립니다',
  },
  {
    id: 5,
    title: '팀',
    text: '세 번째 동료가 합류했다.\n\n이제 "팀"이라고 불러도 될 것 같다.\n\n함께라면 조금 더 멀리, 조금 더 빠르게.',
    unlockHint: '캐릭터를 3명 보유하면 열립니다',
  },
  {
    id: 8,
    title: '기록의 끝',
    text: '5000m.\n\n아무도 이 깊이까지 달려온 적이 없다고 기록은 말한다.\n\n하지만 기록은 틀렸다.',
    unlockHint: '달린 거리 5000m를 넘기면 열립니다',
  },
  {
    id: 9,
    title: '다섯의 연대',
    text: '다섯 명이 모였다.\n\n제각각 다른 능력, 다른 이유.\n\n하지만 같은 방향을 보고 있다.',
    unlockHint: '캐릭터를 5명 보유하면 열립니다',
  },
  {
    id: 10,
    title: '치비의 귀환',
    text: '치비는 50번 넘어졌다.\n\n그리고 50번 다시 일어났다.\n\n처음 시작이 항상 가장 순수하다.',
    unlockHint: '치비로 50회 이상 플레이하면 열립니다',
  },
  {
    id: 11,
    title: '토파즈 빛',
    text: '토파즈는 이 공간이 보상으로 만들어낸 유일한 진짜 조각이다.\n\n30개. 충분히 빛난다.\n\n모은 것들이 이야기가 됐다.',
    unlockHint: '토파즈똥을 30개 이상 모으면 열립니다',
  },
  {
    id: 12,
    title: '끝없는 길',
    text: '10000m.\n\n이 공간에 끝이 있는지 이제는 묻지 않는다.\n\n달리는 것 자체가 답이다.',
    unlockHint: '달린 거리 10000m를 넘기면 열립니다',
  },
  {
    id: 13,
    title: '완전체',
    text: '모든 신호가 모였다.\n\n이제 이 세계 전체를 볼 수 있다.\n\n그리고 깨닫는다 — 이건 게임이 아니었다.',
    unlockHint: '모든 캐릭터를 수집하면 열립니다',
  },
];

