1	import type Phaser from 'phaser';
2	import { GameMode, GAME_MODES, type GameModeConfig } from '../types/GameMode';
3	import { getSkorBalance, getCachedSkorBalance, cacheSkorBalance } from '../utils/skor';
4	import { setBgmMuted } from '../utils/settings';
5	import BaseScene from './BaseScene';
6	
7	export default class ModeSelectScene extends BaseScene {
8	  private skorText!: Phaser.GameObjects.Text;
9	  private settingsPanel: Phaser.GameObjects.Container | null = null;
10	
11	  constructor() {
12	    super('ModeSelectScene');
13	  }
14	
15	  preload() {
16	    if (!this.textures.exists('background2')) {
17	      this.load.image('background2', 'assets/backgrounds/background2.webp');
18	    }
19	    if (!this.textures.exists('title')) {
20	      this.load.image('title', 'assets/title.webp');
21	    }
22	  }
23	
24	  create() {
25	    super.create();
26	
27	    const W = this.scale.width;
28	    const H = this.scale.height;
29	    const cx = W / 2;
30	    const yOff = (H - 600) / 2;
31	
32	    const background = this.add.image(cx, H / 2, 'background2');
33	    background.setDisplaySize(W, H);
34	
35	    const title = this.add.image(cx, 90 + yOff, 'title');
36	    title.setScale(0.4);
37	
38	    this.add.text(cx, 190 + yOff, '모드를 선택하세요', {
39	      fontSize: '20px',
40	      color: '#fff',
41	      fontStyle: 'bold',
42	      stroke: '#000',
43	      strokeThickness: 4
44	    }).setOrigin(0.5);
45	
46	    // 클래식 + 대전 모드 버튼 (같은 줄, 캐릭터/랭킹 버튼과 동일 크기)
47	    this.createModeButton(GAME_MODES[0], cx - 80, 250 + yOff);
48	    this.createBattleButton(cx + 80, 250 + yOff);
49	
50	    // 뽑기 버튼 (SKOR 잔액 포함)
51	    this.createGachaButton(cx, 345 + yOff);
52	
53	    // 하단 버튼 행: 캐릭터 선택 + 랭킹
54	    this.createCharacterButton(cx - 80, 435 + yOff);
55	    this.createLeaderboardButton(cx + 80, 435 + yOff);
56	
57	    // 릴리즈 노트 링크
58	    this.createReleaseNotesLink(cx, H - 80);
59	
60	    // 설정 버튼 (우하단)
61	    this.createSettingsButton(W - 26, H - 26);
62	
63	    // SKOR 잔액 비동기 로드
64	    this.loadSkorBalance();
65	  }
66	
67	  private async loadSkorBalance() {
68	    try {
69	      const balance = await getSkorBalance();
70	      cacheSkorBalance(balance);
71	      if (this.skorText?.active) {
72	        this.skorText.setText(`💰 ${Math.floor(balance)} SKOR`);
73	      }
74	    } catch {
75	      // 잔액 로드 실패 시 캐시 값 유지
76	    }
77	  }
78	
79	  private createModeButton(modeConfig: GameModeConfig, x: number, y: number) {
80	    const button = this.add.rectangle(x, y, 140, 70, 0xffffff, 1);
81	    button.setStrokeStyle(3, 0x000000);
82	
83	    const titleText = this.add.text(x, y, modeConfig.name, {
84	      fontSize: '18px',
85	      color: '#000',
86	      fontStyle: 'bold'
87	    }).setOrigin(0.5);
88	
89	    button.setInteractive({ useHandCursor: true });
90	    titleText.setInteractive({ useHandCursor: true });
91	
92	    [button, titleText].forEach(element => {
93	      element.on('pointerover', () => button.setFillStyle(0xffff99));
94	      element.on('pointerout',  () => button.setFillStyle(0xffffff));
95	      element.on('pointerdown', () => this.startGame(modeConfig.mode));
96	    });
97	  }
98	
99	  private createBattleButton(x: number, y: number) {
100	    const button = this.add.rectangle(x, y, 140, 70, 0xe74c3c, 1);
101	    button.setStrokeStyle(3, 0xc0392b);
102	
103	    const titleText = this.add.text(x, y, '⚔️ 대전 모드', {
104	      fontSize: '18px',
105	      color: '#ffffff',
106	      fontStyle: 'bold',
107	      padding: { top: 4 },
108	    }).setOrigin(0.5);
109	
110	    button.setInteractive({ useHandCursor: true });
111	    titleText.setInteractive({ useHandCursor: true });
112	
113	    [button, titleText].forEach(el => {
114	      el.on('pointerover', () => {
115	        button.setFillStyle(0xff6b6b);
116	        button.setStrokeStyle(3, 0xff4444);
117	      });
118	      el.on('pointerout', () => {
119	        button.setFillStyle(0xe74c3c);
120	        button.setStrokeStyle(3, 0xc0392b);
121	      });
122	      el.on('pointerdown', () => {
123	        this.scene.start('BattleMatchScene');
124	      });
125	    });
126	  }
127	
128	  private createGachaButton(x: number, y: number) {
129	    const button = this.add.rectangle(x, y, 300, 75, 0x1a1a2e, 1);
130	    button.setStrokeStyle(3, 0x7b2fff);
131	
132	    // 뽑기 타이틀
133	    this.add.text(x, y - 22, '🎰 캐릭터 뽑기', {
134	      fontSize: '22px',
135	      color: '#ffffff',
136	      fontStyle: 'bold',
137	      padding: { top: 4 },
138	    }).setOrigin(0.5);
139	
140	    // SKOR 잔액 — 캐시 값 즉시 표시
141	    const cached = getCachedSkorBalance();
142	    const initialSkorLabel = cached !== null ? `💰 ${cached} SKOR` : '💰 -- SKOR';
143	    this.skorText = this.add.text(x, y + 8, initialSkorLabel, {
144	      fontSize: '16px',
145	      color: '#c0a0ff',
146	      padding: { top: 3 },
147	    }).setOrigin(0.5);
148	
149	    // 비용 안내
150	    this.add.text(x, y + 28, '1회 100 · 10회 900', {
151	      fontSize: '12px',
152	      color: '#888888',
153	    }).setOrigin(0.5);
154	
155	    button.setInteractive({ useHandCursor: true });
156	
157	    button.on('pointerover', () => {
158	      button.setFillStyle(0x2d1a5e);
159	      button.setStrokeStyle(3, 0xaa66ff);
160	    });
161	    button.on('pointerout', () => {
162	      button.setFillStyle(0x1a1a2e);
163	      button.setStrokeStyle(3, 0x7b2fff);
164	    });
165	    button.on('pointerdown', () => {
166	      this.scene.start('GachaScene');
167	    });
168	  }
169	
170	  private createCharacterButton(x: number, y: number) {
171	    const button = this.add.rectangle(x, y, 140, 70, 0x2a2a2a, 1);
172	    button.setStrokeStyle(2, 0x888888);
173	
174	    this.add.text(x, y, '🧬 캐릭터', {
175	      fontSize: '18px',
176	      color: '#ffffff',
177	      fontStyle: 'bold',
178	      padding: { top: 4 },
179	    }).setOrigin(0.5);
180	
181	    button.setInteractive({ useHandCursor: true });
182	
183	    button.on('pointerover', () => button.setFillStyle(0x444444));
184	    button.on('pointerout',  () => button.setFillStyle(0x2a2a2a));
185	    button.on('pointerdown', () => {
186	      this.scene.start('CharacterSelectScene');
187	    });
188	  }
189	
190	  private createLeaderboardButton(x: number, y: number) {
191	    const button = this.add.rectangle(x, y, 140, 70, 0x4a90e2, 1);
192	    button.setStrokeStyle(2, 0x2e5c8a);
193	
194	    this.add.text(x, y, '🏆 랭킹', {
195	      fontSize: '18px',
196	      color: '#fff',
197	      fontStyle: 'bold',
198	      padding: { top: 4 },
199	    }).setOrigin(0.5);
200	
201	    button.setInteractive({ useHandCursor: true });
202	
203	    button.on('pointerover', () => button.setFillStyle(0x5ba3f5));
204	    button.on('pointerout',  () => button.setFillStyle(0x4a90e2));
205	    button.on('pointerdown', () => {
206	      this.scene.start('LeaderboardScene');
207	    });
208	  }
209	
210	  private createReleaseNotesLink(x: number, y: number) {
211	    const text = this.add.text(x, y, '📋 릴리즈 노트', {
212	      fontSize: '15px',
213	      color: '#cccccc',
214	      stroke: '#000',
215	      strokeThickness: 3,
216	      padding: { top: 3 },
217	    }).setOrigin(0.5);
218	
219	    text.setInteractive({ useHandCursor: true });
220	    text.on('pointerover', () => text.setColor('#FFD700'));
221	    text.on('pointerout',  () => text.setColor('#cccccc'));
222	    text.on('pointerdown', () => this.scene.start('ReleaseNotesScene'));
223	  }
224	
225	  private createSettingsButton(x: number, y: number) {
226	    const btn = this.add.text(x, y, '⚙️', {
227	      fontSize: '34px',
228	      padding: { top: 6 },
229	    }).setOrigin(0.5).setDepth(11).setInteractive({ useHandCursor: true });
230	
231	    // 이모지 바운딩 박스 중심에 원 정렬
