) {
  this.handleGoldCollected(_goldPoop as GoldPoop);
}

private handleDiamondCollected(poop: Phaser.Physics.Arcade.Sprite) {
  this.handleSpecialCollected(poop, 'diamond', 40, '💎', '#00FFFF', () => { this.diamondCollected++; });
}

