    const yOff = (this.scale.height - 600) / 2;
    this.terminalBaseY = 276 + yOff;

    this.add.rectangle(cx, 342 + yOff, 370, 172, 0x000000)
      .setStrokeStyle(1, borderColor, 0.8);
