  private addPullButton(x: number, y: number, label: string, cost: string, type: 'single' | 'multi') {
    const accentColor = type === 'single' ? 0xddaa00 : 0x7b2fff;
    const accentHex   = type === 'single' ? '#ddaa00' : '#aa88ff';

